static const char kk_dgc_pipeline_shader[] = "/* Apple10 execution-set commands keep Vulkan's common raster state on the\n * encoder (all entries must define identical static/dynamic state). */\nstruct PipelineRow {\n   Params p;\n   render_pipeline_state render;\n   compute_pipeline_state compute;\n   depth_stencil_state depth;\n   uint valid, has_depth;\n};\nstruct PipelineState {\n   Params p;\n   ulong rows;\n   uint pipeline_offset, pipeline_count, target, pad;\n};\nstatic_assert(sizeof(PipelineRow) == KK_DGC_PIPELINE_ROW_SIZE, \"pipeline row ABI\");\nstatic_assert(sizeof(PipelineState) == KK_DGC_PIPELINE_STATE_SIZE, \"pipeline state ABI\");\nstatic Params kk_dgc_pipeline_params(constant PipelineState &s, const device PipelineRow &row) {\n   Params q = row.p;\n   q.first = s.p.first; q.maximum = s.p.maximum;\n   q.output = s.p.output; q.execution_range = s.p.execution_range;\n   return q;\n}\nkernel void kk_dgc_pipeline_commands(constant PipelineState &s [[buffer(KK_ARGUMENT_ROOT)]],\n   constant ICB &icb [[buffer(KK_ARGUMENT_SAMPLERS)]], uint i [[thread_position_in_grid]]) {\n   constant Params &p = s.p;\n   if (i >= p.maximum) return;\n   uint count = p.count ? min(*(const device uint *)p.count, p.maximum + p.first) : p.maximum + p.first;\n   if (p.condition && ((*(const device uint *)p.condition != 0) == bool(p.inverted))) count = 0;\n   uint active = count > p.first ? min(count - p.first, p.maximum) : 0;\n   if (i == 0) { device uint *range = (device uint *)p.execution_range; range[0] = 0; range[1] = active; }\n   if (i >= active) return;\n   const device uchar *src = (const device uchar *)p.stream + ulong(p.first + i) * p.stream_stride;\n   uint index = *(const device uint *)(src + s.pipeline_offset);\n   if (p.action == 2) { compute_command cmd(icb.commands, i); cmd.reset(); }\n   else { render_command cmd(icb.commands, i); cmd.reset(); }\n   if (index >= s.pipeline_count) return;\n   const device PipelineRow &row = ((const device PipelineRow *)s.rows)[index];\n   if (!row.valid) return;\n   Params q = kk_dgc_pipeline_params(s, row);\n   kk_dgc_expand_thread(q, i, true);\n   device uchar *record = (device uchar *)q.output + ulong(i) * q.record_stride;\n   const device uint *args = (const device uint *)(record + q.args_offset);\n   device uchar *root = q.root_size ? record : (device uchar *)q.base_root;\n   if (q.action == 2) {\n      if (!args[0] || !args[1] || !args[2]) return;\n      compute_command cmd(icb.commands, i);\n      cmd.set_compute_pipeline_state(row.compute);\n      cmd.set_kernel_buffer(root, KK_ARGUMENT_ROOT);\n      cmd.set_kernel_buffer((device void *)q.samplers, KK_ARGUMENT_SAMPLERS);\n      cmd.concurrent_dispatch_threadgroups(uint3(args[0],args[1],args[2]), uint3(q.local));\n   } else {\n      if (!args[0] || !args[1]) return;\n      render_command cmd(icb.commands, i);\n      cmd.set_render_pipeline_state(row.render);\n      if (row.has_depth) cmd.set_depth_stencil_state(row.depth);\n      cmd.set_vertex_buffer(root, KK_ARGUMENT_ROOT); cmd.set_fragment_buffer(root, KK_ARGUMENT_ROOT);\n      cmd.set_vertex_buffer((device void *)q.samplers, KK_ARGUMENT_SAMPLERS); cmd.set_fragment_buffer((device void *)q.samplers, KK_ARGUMENT_SAMPLERS);\n      cmd.set_vertex_buffer(record + q.draw_offset, KK_ARGUMENT_PER_DRAW); cmd.set_fragment_buffer(record + q.draw_offset, KK_ARGUMENT_PER_DRAW);\n      if (q.layer_replay) {\n         cmd.set_vertex_buffer((device void *)0, KK_ARGUMENT_POLY_LAYER_REPLAY);\n         cmd.set_fragment_buffer((device void *)0, KK_ARGUMENT_POLY_LAYER_REPLAY);\n      }\n      if (q.linked_vs_buffer) cmd.set_vertex_buffer((device void *)q.linked_vs_buffer, KK_ARGUMENT_VS_VFT_WRAPPER);\n      if (q.linked_fs_buffer) cmd.set_fragment_buffer((device void *)q.linked_fs_buffer, KK_ARGUMENT_FS_VFT_WRAPPER);\n      if (q.interlock_guard) cmd.set_fragment_buffer((device void *)q.interlock_guard, KK_ARGUMENT_INTERLOCK_GUARD);\n      if (q.action == 1) {\n         const device uchar *binding = record + q.index_offset;\n         ulong address = kk_dgc_address(binding); uint size = *(const device uint *)(binding + 8);\n         if (size == 2) cmd.draw_indexed_primitives(primitive_type(q.primitive), args[0], (const device ushort *)address + args[2], args[1], int(args[3]), args[4]);\n         else cmd.draw_indexed_primitives(primitive_type(q.primitive), args[0], (const device uint *)address + args[2], args[1], int(args[3]), args[4]);\n      } else cmd.draw_primitives(primitive_type(q.primitive), args[2], args[0], args[1], args[3]);\n   }\n}\n/* GPU filter for ordinary shared Poly/descriptor-load replay. CPU recording\n * never reads the selector/count/predicate; only the matching user body runs. */\nkernel void kk_dgc_pipeline_filter(constant PipelineState &s [[buffer(KK_ARGUMENT_ROOT)]],\n   constant uint &sequence [[buffer(KK_ARGUMENT_SAMPLERS)]]) {\n   constant Params &p = s.p;\n   const device PipelineRow &row = ((const device PipelineRow *)s.rows)[s.target];\n   Params q = row.p; q.first = sequence; q.maximum = 1; q.output = p.output;\n   uint count = p.count ? min(*(const device uint *)p.count, p.maximum) : p.maximum;\n   bool enabled = sequence < count;\n   if (p.condition) enabled &= ((*(const device uint *)p.condition != 0) != bool(p.inverted));\n   if (enabled) {\n      const device uchar *src = (const device uchar *)p.stream + ulong(sequence) * p.stream_stride;\n      enabled = *(const device uint *)(src + s.pipeline_offset) == s.target;\n   }\n   kk_dgc_expand_thread(q, 0, enabled);\n}\n";
